#ifndef MC_BLOCKS_H
#define MC_BLOCKS_H
#include <stdint.h>
/* Render models and procedural texture recipes generated by tools/blockinfo.py. */
enum { MM_NONE, MM_CUBE, MM_LIQUID, MM_BOXES, MM_CROSS, MM_FLAT, MM_PLATE, MM_SNOW, MM_TORCH };
enum { MF_OPAQUE = 1, MF_WATER = 2, MF_EMISSIVE = 4, MF_LEAVES = 8, MF_SAMECULL = 16, MF_AXIS = 32 };
enum { MC_PASS_OPAQUE, MC_PASS_CUTOUT, MC_PASS_TRANSLUCENT, MC_PASSES };
enum {
    TP_FLAT, TP_STONE, TP_DIRT, TP_GRASS_TOP, TP_GRASS_SIDE, TP_SAND, TP_GRAVEL, TP_COBBLE, TP_PLANKS,
    TP_LOG_SIDE, TP_LOG_TOP, TP_LEAVES, TP_ORE, TP_BRICKS, TP_STONE_BRICKS, TP_TILES, TP_METAL, TP_WOOL,
    TP_GLASS, TP_STAINED_GLASS, TP_WATER, TP_LAVA, TP_PLANT, TP_FLOWER, TP_CROP, TP_SNOW, TP_ICE,
    TP_ICE_SOLID, TP_BEDROCK, TP_OBSIDIAN, TP_SANDSTONE, TP_GLAZED, TP_GLOW, TP_MACHINE, TP_BOOKS,
    TP_CACTUS, TP_TORCH, TP_RAIL, TP_WIRE
};
typedef struct { uint16_t low, high; uint8_t model, pass, flags; uint16_t top, side, bottom; } McBlockDef;
typedef struct { uint8_t pattern; uint32_t c1, c2; } McTexDef;
#define MC_TILE 16
#define MC_ATLAS_TILES 32
#define MC_ATLAS_SIZE (MC_TILE*MC_ATLAS_TILES)
/* Writes an RGBA atlas in memory byte order R,G,B,A. Returns the number of tiles. */
unsigned mc_textures_build(uint32_t atlas[MC_ATLAS_SIZE*MC_ATLAS_SIZE]);
const McBlockDef *mc_block_def(uint16_t state);
#endif
